import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('retains reported counts when a provider reuses its usage object (specs/hal-engine-config-hooks/spec.md#10)', async () => {
  const usage = {inputTokens: 2, outputTokens: 3, totalTokens: 5};
  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      if (round++ === 0) {
        yield {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}};
        yield {type: 'stop', stopReason: 'tool_use', usage};
        return;
      }
      Object.assign(usage, {inputTokens: 7, outputTokens: 11, totalTokens: 18});
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> { return {} as T; },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
  let total: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), registry, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { total = usage; }},
  });
  const session: ChatSession = {sessionId: 's', userId: 'u', entries: [{role: 'user', content: 'Hi', timestamp: '2026-01-01T00:00:00.000Z'}]};
  await orchestrator.processMessage(session);
  expect(total).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
});
EOF
